import { DraggableSelection } from './dragging';

export class BarlineSelection extends DraggableSelection {
  public drag_cb: (x: number) => void;

  constructor(drag: (x: number) => void, createdByMouseDown: boolean) {
    super(createdByMouseDown);
    this.drag_cb = drag;
  }

  override mouseDrag(x: number) {
    this.drag_cb(x);
  }
}
