import type { IScore } from '../Score';
import type { Pitch } from '../global/pitch';

export abstract class ISelection {
  abstract dragging(): boolean;
  abstract dragOverPitch(pitch: Pitch, score: IScore): void;
  abstract mouseDrag(x: number, y: number, score: IScore, page: number): void;
  abstract mouseUp(): void;
  // Returns the new selection if there is one
  abstract delete(score: IScore): ISelection | null;
}
